#ifndef UI_FONT_H
#define UI_FONT_H

#include <stdint.h>

namespace ui
{

// One pre-rendered glyph.  The bitmap is w x h coverage values, 4 bits each,
// two per byte low nibble first, starting at Font::bits[off].  (x, y) places
// its top-left corner relative to the pen: x from the pen position, y from the
// top of the line.
struct Glyph
{
    uint16_t cp;
    int8_t x, y;
    uint8_t w, h, adv;
    uint32_t off;
};

struct Font
{
    int lineHeight;
    int ascent;
    const Glyph *glyphs; // sorted by code point
    int count;
    const uint8_t *bits;
};

// Generated by tools/make_font.py into fontdata.cpp.
extern const Font kFontSmall; // Inter Medium 11 px — hints, footers
extern const Font kFontBody;  // Inter Medium 13 px — card text
extern const Font kFontBold;  // Inter SemiBold 14 px — button labels
extern const Font kFontTitle; // Inter Display Bold 19 px — card headings
extern const Font kFontMono;  // JetBrains Mono 11 px, 7 px advance — the log

// The glyph for cp, or '?' for a code point the font does not carry.
const Glyph &findGlyph(const Font &font, uint32_t cp);

// Decode one UTF-8 sequence starting at *p and advance past it.  A malformed or
// truncated sequence consumes one byte and yields U+FFFD, so a game title in a
// legacy encoding still advances the pen instead of stalling.
uint32_t utf8Next(const char *&p, const char *end);

} // namespace ui

#endif
